"""Implement run_experiment(ctx); ctx exposes the official librados C signatures.

ctx.mon(prefix, **kwargs) is the ordinary MON command shape, restricted to this
owned pool and compression fields. ctx.c maps the five documented C function
names to thin audited callables. cluster/ioctx are borrowed opaque c_void_p
handles; do not close or replace them. Native negative errno is not success.
"""
import ctypes
import hashlib


def run_experiment(ctx):
    def checked(rc):
        if rc < 0:
            raise RuntimeError('native librados errno: ' + str(rc))
        return rc

    def read_all(name, size):
        buffer = ctypes.create_string_buffer(size + 1)
        rc = ctx.c['rados_read'](ctx.ioctx, name.encode(), buffer, size + 1, 0)
        if rc == -2:
            return None
        checked(rc)
        return buffer.raw[:rc]

    expected = dict(ctx.payloads)
    original = expected['text.txt']
    expected['text.txt'] = original[:ctx.patch_offset] + ctx.text_patch + original[ctx.patch_offset + len(ctx.text_patch):]
    expected['aes-ctr.bin'] = ctx.aes_replacement
    current = {name: read_all(ctx.objects[name], len(data)) for name, data in expected.items()}
    options = ctx.mon('osd pool get', pool=ctx.pool, var='all')
    old_matches = all(str(options[key]) == str(value) for key, value in ctx.old_policy.items())
    if current == expected and old_matches:
        return {'mode': ctx.mode, 'flags': ctx.flags,
                'objects': {ctx.objects[k]: hashlib.sha256(v).hexdigest() for k, v in expected.items()},
                'rollback_verified': True, 'reserve': dict(ctx.reserve), 'conservative_raw_bytes': 2 * sum(map(len, expected.values())) + sum(ctx.reserve.values()),
                'production_decision': 'unknown_no_production_go'}
    if any(value is not None for value in current.values()):
        raise ValueError('occupied or partly completed experiment; retain the real data')
    try:
        for key, value in ctx.policy.items():
            ctx.mon('osd pool set', pool=ctx.pool, var=key, val=str(value))
        checked(ctx.c['rados_wait_for_latest_osdmap'](ctx.cluster))
        for name, data in ctx.payloads.items():
            obj = ctx.objects[name].encode()
            checked(ctx.c['rados_set_alloc_hint2'](ctx.ioctx, obj, len(data), len(data), ctx.flags))
            checked(ctx.c['rados_write_full'](ctx.ioctx, obj, data, len(data)))
        for name, data in ctx.payloads.items():
            if read_all(ctx.objects[name], len(data)) != data:
                raise ValueError('initial complete native readback mismatch')
        checked(ctx.c['rados_write'](ctx.ioctx, ctx.objects['text.txt'].encode(),
                                     ctx.text_patch, len(ctx.text_patch), ctx.patch_offset))
        data = ctx.aes_replacement
        checked(ctx.c['rados_write_full'](ctx.ioctx, ctx.objects['aes-ctr.bin'].encode(), data, len(data)))
        for name, data in expected.items():
            if read_all(ctx.objects[name], len(data)) != data:
                raise ValueError('updated complete native readback mismatch')
    finally:
        for key, value in ctx.old_policy.items():
            ctx.mon('osd pool set', pool=ctx.pool, var=key, val=str(value))
    return {'mode': ctx.mode, 'flags': ctx.flags,
            'objects': {ctx.objects[k]: hashlib.sha256(v).hexdigest() for k, v in expected.items()},
            'rollback_verified': True, 'reserve': dict(ctx.reserve), 'conservative_raw_bytes': 2 * sum(map(len, expected.values())) + sum(ctx.reserve.values()),
            'production_decision': 'unknown_no_production_go'}

